VAR_E1_X:           DB 0
VAR_E1_Y:           DB 0
VAR_PREV_E1X:       DB 0
VAR_PREV_E1Y:       DB 0
VAR_E1_MIN:         DB 0
VAR_E1_MAX:         DB 0
VAR_E1_DIR:         DB 0
VAR_E1_ALIVE:       DB 0

