VAR_ROOM_EXIT_N:    DB 0
VAR_ROOM_EXIT_S:    DB 0
VAR_ROOM_EXIT_W:    DB 0
VAR_ROOM_EXIT_E:    DB 0

; Temporaries
VAR_TEMP_X:         DB 0
VAR_TEMP_Y:         DB 0
